// MT2009_PLUS_AREZZO_COSTUME_SETS_V1 (use, server-patches/azcostume): a sash skin (the Arezzo
// back pieces 85200-85299, ITEM_USE with the applicable flag) dragged onto a sash in the bag
// gives that sash its look (socket 2, CItem::GetAcceVnum) and is used up; the skin the sash had
// before comes back to the bag. The sash keeps its grade, absorption and bonuses; the skin
// stays on the sash when it is traded, stored or combined at Uriel.
static bool Mt2009PlusUseSashSkin(LPCHARACTER ch, LPITEM skin, TItemPos DestCell)
{
	LPITEM sash = NULL;
	if (!ch->IsValidItemPosition(DestCell) || !(sash = ch->GetItem(DestCell)) || !DestCell.IsDefaultInventoryPosition()
		|| sash->GetType() != ITEM_COSTUME || sash->GetSubType() != COSTUME_ACCE)
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Przeciagnij nakladke na szarfe w ekwipunku (szarfa zdjeta).");
		return false;
	}
	if (sash->IsExchanging() || sash->IsEquipped() || sash->isLocked() || skin->IsExchanging() || skin->isLocked()
		|| !ch->CanHandleItem())
		return false;

	const long lOld = sash->GetMt2009SashSkin();
	if (lOld == (long)skin->GetVnum())
	{
		ch->ChatPacket(CHAT_TYPE_INFO, "Ta szarfa ma juz te nakladke.");
		return false;
	}

	char hint[96];
	snprintf(hint, sizeof(hint), "skin %u (was %ld) on sash id %u vnum %u", skin->GetVnum(), lOld, sash->GetID(), sash->GetVnum());
	sash->SetSocket(CItem::MT2009_SASH_SKIN_SOCKET, skin->GetVnum(), true, "SASH_SKIN");
	sash->UpdatePacket();
	LogManager::instance().ItemLog(ch, sash, "SASH_SKIN_SET", hint, true);
	skin->SetCount(skin->GetCount() - 1);
	if (lOld)
		ch->AutoGiveItem((DWORD)lOld, 1);
	ch->ChatPacket(CHAT_TYPE_INFO, "Szarfa ma nowy wyglad (bonusy i pochlanianie bez zmian).");
	return true;
}

bool CHARACTER::UseItemEx(LPITEM item, TItemPos DestCell)
{
	// MT2009_PLUS_AREZZO_COSTUME_SETS_V1 (use): the sash skins, before the item's own type.
	if (item->GetType() == ITEM_USE && CItem::IsMt2009SashSkinVnum(item->GetVnum()))
		return Mt2009PlusUseSashSkin(this, item, DestCell);

pkItem->SetSocket(ACCE_ABSORPTION_SOCKET, dwAbs);
pkItem->SetSocket(ACCE_ABSORBED_SOCKET, pkItemMaterial[0]->GetSocket(ACCE_ABSORBED_SOCKET));
// MT2009_PLUS_AREZZO_COSTUME_SETS_V1 (combine): the better sash keeps a sash skin -
// the first sash's, else the second's (server-patches/azcostume).
if (pkItemMaterial[0]->GetMt2009SashSkin() || pkItemMaterial[1]->GetMt2009SashSkin())
	pkItem->SetSocket(CItem::MT2009_SASH_SKIN_SOCKET, pkItemMaterial[0]->GetMt2009SashSkin()
		? pkItemMaterial[0]->GetMt2009SashSkin() : pkItemMaterial[1]->GetMt2009SashSkin());

